// InterleaveRoPE op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Format: platform_ascendc + EXEC_KERNEL_CMD
// Inputs are flattened (total_rows, D) 2D tensors

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_interleave_rope.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_ROWS = 16;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor interleave_rope(
    const at::Tensor &x,
    const at::Tensor &cos,
    const at::Tensor &sin)
{
    // Input validation
    TORCH_CHECK(x.dim() == 2, "x must be 2D (total_rows, D)");
    TORCH_CHECK(cos.dim() == 2, "cos must be 2D (total_rows, D)");
    TORCH_CHECK(sin.dim() == 2, "sin must be 2D (total_rows, D)");
    TORCH_CHECK(
        x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16,
        "x must be float16 or bfloat16");
    TORCH_CHECK(cos.scalar_type() == x.scalar_type(),
        "cos must have the same dtype as x");
    TORCH_CHECK(sin.scalar_type() == x.scalar_type(),
        "sin must have the same dtype as x");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(cos.is_contiguous(), "cos must be contiguous");
    TORCH_CHECK(sin.is_contiguous(), "sin must be contiguous");
    TORCH_CHECK(x.sizes() == cos.sizes() && x.sizes() == sin.sizes(),
        "x, cos, sin must have the same shape");

    int32_t totalRows = static_cast<int32_t>(x.sizes()[0]);
    int32_t D = static_cast<int32_t>(x.sizes()[1]);
    TORCH_CHECK(D % 2 == 0, "D must be even");

    // Compute tiling — distribute row blocks across cores
    int32_t rowBlocks = (totalRows + DEFAULT_BLOCK_ROWS - 1) / DEFAULT_BLOCK_ROWS;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                             std::max<int32_t>(1, rowBlocks));
    int32_t tasksPerCore = (rowBlocks + usedCoreNum - 1) / usedCoreNum;

    // Allocate output
    at::Tensor y = at::empty_like(x);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockRows = DEFAULT_BLOCK_ROWS;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(interleave_rope, blockDim,
                    x, cos, sin, y,
                    totalRows, D, blockRows, usedCoreNum, tasksPerCore,
                    dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
