100	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalElems);
101	        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cosGm), totalElems);
102	        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sinGm), totalElems);
103	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalElems);
