113	        // Typed buffers for GM↔UB data movement
114	        // x_even: D/2 elements, x_odd: D/2 elements (loaded with stride from GM)
115	        pipe.InitBuffer(xEvenQueue_, BUFFER_NUM, halfElems * sizeof(dataType));
116	        pipe.InitBuffer(xOddQueue_, BUFFER_NUM, halfElems * sizeof(dataType));
117	        pipe.InitBuffer(cosQueue_, BUFFER_NUM, fullElems * sizeof(dataType));
118	        pipe.InitBuffer(sinQueue_, BUFFER_NUM, fullElems * sizeof(dataType));
119	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, fullElems * sizeof(dataType));
