123	        pipe.InitBuffer(oddBuf_, halfElems * sizeof(float));
124	        pipe.InitBuffer(cosBuf_, fullElems * sizeof(float));
125	        pipe.InitBuffer(sinBuf_, fullElems * sizeof(float));
126	        pipe.InitBuffer(outBuf_, fullElems * sizeof(float));
127	        pipe.InitBuffer(negOddBuf_, halfElems * sizeof(float));
128	        pipe.InitBuffer(tmpBuf_, halfElems * sizeof(float));
129	
130	        // Cast buffers for non-float types
131	        if constexpr (!std::is_same_v<dataType, float>) {
132	            pipe.InitBuffer(evenCastBuf_, halfElems * sizeof(float));
133	            pipe.InitBuffer(oddCastBuf_, halfElems * sizeof(float));
134	            pipe.InitBuffer(cosCastBuf_, fullElems * sizeof(float));
135	            pipe.InitBuffer(sinCastBuf_, fullElems * sizeof(float));
136	            pipe.InitBuffer(yCastBuf_, fullElems * sizeof(float));
137	        }
138	    }
139	
140	    __aicore__ inline void Process()
141	    {
142	        if ASCEND_IS_AIV {
143	            const int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
144	            const int32_t rowBlocks = CeilDivU32(static_cast<uint32_t>(totalRows),
145	                                                  static_cast<uint32_t>(blockRows));
146	
147	            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
148	                const int32_t bx = coreIdx * tasksPerCore + localIdx;
149	                if (bx >= rowBlocks) { continue; }
150	
151	                const int32_t rowStart = bx * blockRows;
152	                const int32_t rowEnd = (rowStart + blockRows <= totalRows)
153	                                           ? (rowStart + blockRows)
154	                                           : totalRows;
155	
156	                for (int32_t row = rowStart; row < rowEnd; ++row) {
157	                    ProcessRow(row);
158	                }
159	            }
160	        }
161	    }
162	
163	private:
164	    __aicore__ inline void CopyInEven(int32_t row)
165	    {
166	        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
167	        evenTypedLocal_ = xEvenQueue_.AllocTensor<dataType>();
168	        LoadGmStrided(evenTypedLocal_, xGM_[offset], static_cast<uint32_t>(D_HALF), 2);
169	        xEvenQueue_.EnQue(evenTypedLocal_);
170	    }
171	
172	    __aicore__ inline void CopyInOdd(int32_t row)
173	    {
174	        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D) + 1;
175	        oddTypedLocal_ = xOddQueue_.AllocTensor<dataType>();
176	        LoadGmStrided(oddTypedLocal_, xGM_[offset], static_cast<uint32_t>(D_HALF), 2);
177	        xOddQueue_.EnQue(oddTypedLocal_);
178	    }
179	
180	    __aicore__ inline void CopyInCos(int32_t row)
181	    {
182	        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
183	        cosTypedLocal_ = cosQueue_.AllocTensor<dataType>();
184	        LoadGmToUb(cosTypedLocal_, cosGM_[offset], static_cast<uint32_t>(D));
185	        cosQueue_.EnQue(cosTypedLocal_);
186	    }
187	
188	    __aicore__ inline void CopyInSin(int32_t row)
189	    {
190	        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
191	        sinTypedLocal_ = sinQueue_.AllocTensor<dataType>();
192	        LoadGmToUb(sinTypedLocal_, sinGM_[offset], static_cast<uint32_t>(D));
193	        sinQueue_.EnQue(sinTypedLocal_);
194	    }
195	
196	    __aicore__ inline void CopyOutY(int32_t row)
197	    {
198	        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
199	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
200	        StoreUbToGm(yGM_[offset], yOutLocal_, static_cast<uint32_t>(D));
201	        yOutQueue_.FreeTensor(yOutLocal_);
202	    }
203	
204	    // Helper: prepare float32 tensor from typed tensor (with optional cast)
205	    template <typename SrcT>
206	    __aicore__ inline void PrepareFloat(
207	        AscendC::LocalTensor<float> &dst,
208	        AscendC::LocalTensor<SrcT> &src,
209	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
210	        int32_t count)
211	    {
212	        if constexpr (std::is_same_v<SrcT, float>) {
213	            dst = src.template ReinterpretCast<float>();
214	        } else {
215	            dst = castBuf.Get<float>();
216	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
217	        }
218	    }
219	
220	    // Helper: finalize float32 tensor to typed tensor (with optional cast)
221	    template <typename DstT>
222	    __aicore__ inline void FinalizeTyped(
223	        AscendC::LocalTensor<DstT> &dst,
224	        AscendC::LocalTensor<float> &src,
225	        int32_t count)
226	    {
227	        if constexpr (!std::is_same_v<DstT, float>) {
228	            AscendC::RoundMode roundMode = AscendC::RoundMode::CAST_NONE;
229	            if constexpr (std::is_same_v<DstT, bfloat16_t>) {
230	                roundMode = AscendC::RoundMode::CAST_ROUND;
231	            }
232	            AscendC::Cast(dst, src, roundMode, count);
233	        }
234	    }
235	
236	    __aicore__ inline void ComputeRow()
237	    {
238	        constexpr int32_t kD = 64;
239	        constexpr int32_t kDHalf = D_HALF;
240	
241	        // Get float32 buffers
242	        evenLocal_ = evenBuf_.Get<float>();
243	        oddLocal_ = oddBuf_.Get<float>();
244	        cosLocal_ = cosBuf_.Get<float>();
245	        sinLocal_ = sinBuf_.Get<float>();
246	        outLocal_ = outBuf_.Get<float>();
247	        negOddLocal_ = negOddBuf_.Get<float>();
248	        tmpLocal_ = tmpBuf_.Get<float>();
249	
250	        // Allocate output typed buffer
251	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
252	
253	        // Dequeue inputs
254	        evenTypedLocal_ = xEvenQueue_.DeQue<dataType>();
255	        oddTypedLocal_ = xOddQueue_.DeQue<dataType>();
256	        cosTypedLocal_ = cosQueue_.DeQue<dataType>();
257	        sinTypedLocal_ = sinQueue_.DeQue<dataType>();
258	
259	        // Cast inputs to float32
260	        PrepareFloat(evenLocal_, evenTypedLocal_, evenCastBuf_, kDHalf);
261	        PrepareFloat(oddLocal_, oddTypedLocal_, oddCastBuf_, kDHalf);
262	        PrepareFloat(cosLocal_, cosTypedLocal_, cosCastBuf_, kD);
263	        PrepareFloat(sinLocal_, sinTypedLocal_, sinCastBuf_, kD);
264	
265	        // ---- Compute ----
266	        // Negate odds for rotation: neg_odds = -odds
267	        AscendC::Muls(negOddLocal_, oddLocal_, -1.0f, kDHalf);
268	
269	        // out_first_half = evens * cos_first_half + (-odds) * sin_first_half
270	        // cos_first_half = cos[0:D/2], sin_first_half = sin[0:D/2]
271	        AscendC::Mul(outLocal_, evenLocal_, cosLocal_, kDHalf);
272	        AscendC::Mul(tmpLocal_, negOddLocal_, sinLocal_, kDHalf);
273	        AscendC::Add(outLocal_, outLocal_, tmpLocal_, kDHalf);
274	
275	        // out_second_half = odds * cos_second_half + evens * sin_second_half
276	        // cos_second_half = cos[D/2:D], sin_second_half = sin[D/2:D]
277	        // Use outLocal_[D/2:] for second half
278	        AscendC::Mul(outLocal_[kDHalf], oddLocal_, cosLocal_[kDHalf], kDHalf);
279	        AscendC::Mul(tmpLocal_, evenLocal_, sinLocal_[kDHalf], kDHalf);
280	        AscendC::Add(outLocal_[kDHalf], outLocal_[kDHalf], tmpLocal_, kDHalf);
281	
282	        // Finalize: cast float32 → dataType
283	        FinalizeTyped(yOutLocal_, outLocal_, kD);
284	
285	        // Free input tensors
286	        xEvenQueue_.FreeTensor(evenTypedLocal_);
287	        xOddQueue_.FreeTensor(oddTypedLocal_);
288	        cosQueue_.FreeTensor(cosTypedLocal_);
289	        sinQueue_.FreeTensor(sinTypedLocal_);
290	
291	        // Enqueue output
292	        yOutQueue_.EnQue(yOutLocal_);
293	    }
294	
295	    __aicore__ inline void ProcessRow(int32_t row)
296	    {
297	        CopyInEven(row);
298	        CopyInOdd(row);
299	        CopyInCos(row);
300	        CopyInSin(row);
301	        ComputeRow();
302	        CopyOutY(row);
303	    }
304	
305	private:
306	    int32_t totalRows = 0;
307	    int32_t D = 0;
308	    int32_t blockRows = 0;
309	    int32_t usedCoreNum = 0;
310	    int32_t tasksPerCore = 0;
311	
312	    AscendC::TPipe pipe;
313	
314	    AscendC::GlobalTensor<dataType> xGM_;
315	    AscendC::GlobalTensor<dataType> cosGM_;
316	    AscendC::GlobalTensor<dataType> sinGM_;
317	    AscendC::GlobalTensor<dataType> yGM_;
318	
319	    // TQue for GM↔UB DMA
320	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xEvenQueue_;
321	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xOddQueue_;
322	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosQueue_;
323	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinQueue_;
324	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
325	
326	    // TBuf for float32 compute
327	    AscendC::TBuf<AscendC::TPosition::VECCALC> evenBuf_;
328	    AscendC::TBuf<AscendC::TPosition::VECCALC> oddBuf_;
329	    AscendC::TBuf<AscendC::TPosition::VECCALC> cosBuf_;
330	    AscendC::TBuf<AscendC::TPosition::VECCALC> sinBuf_;
331	    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf_;
332	    AscendC::TBuf<AscendC::TPosition::VECCALC> negOddBuf_;
333	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
334	
335	    // TBuf for Cast
336	    AscendC::TBuf<AscendC::TPosition::VECCALC> evenCastBuf_;
337	    AscendC::TBuf<AscendC::TPosition::VECCALC> oddCastBuf_;
338	    AscendC::TBuf<AscendC::TPosition::VECCALC> cosCastBuf_;
339	    AscendC::TBuf<AscendC::TPosition::VECCALC> sinCastBuf_;
340	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
341	
342	    // Local tensors (typed)
343	    AscendC::LocalTensor<dataType> evenTypedLocal_;
344	    AscendC::LocalTensor<dataType> oddTypedLocal_;
345	    AscendC::LocalTensor<dataType> cosTypedLocal_;
346	    AscendC::LocalTensor<dataType> sinTypedLocal_;
347	    AscendC::LocalTensor<dataType> yOutLocal_;
348	
349	    // Local tensors (float32)
350	    AscendC::LocalTensor<float> evenLocal_;
351	    AscendC::LocalTensor<float> oddLocal_;
352	    AscendC::LocalTensor<float> cosLocal_;
353	    AscendC::LocalTensor<float> sinLocal_;
354	    AscendC::LocalTensor<float> outLocal_;
355	    AscendC::LocalTensor<float> negOddLocal_;
356	    AscendC::LocalTensor<float> tmpLocal_;
357	};
358	
359	// =========================================================================
360	// Kernel entry point (One prim_func → one kernel class → one __global__ entry)
361	// =========================================================================
362	
363	extern "C" __global__ __aicore__ void interleave_rope(
364	    GM_ADDR xGm, GM_ADDR cosGm, GM_ADDR sinGm, GM_ADDR yGm,
365	    int32_t totalRows, int32_t D, int32_t blockRows,
366	    int32_t usedCoreNum, int32_t tasksPerCore,
367	    int64_t dtypeFlag)
368	{
369	    if (dtypeFlag == 0) {
370	        InterleaveRopeKernel<float> kernel;
371	        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
372	        kernel.Process();
373	    } else if (dtypeFlag == 1) {
374	        InterleaveRopeKernel<half> kernel;
375	        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
376	        kernel.Process();
377	    } else {
378	        InterleaveRopeKernel<bfloat16_t> kernel;
379	        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
380	        kernel.Process();
381	    }
382	}
