 */

// AscendC InterleaveRoPE kernel
// Supports float16 and bfloat16, internal float32 compute
// Interleave pattern: evens [x0,x2,...,x62], odds [x1,x3,...,x63]
// Rotation: first_half=-odds, second_half=evens
// Output: interleaved*cos + rotated*sin

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t D_CONST = 64;
constexpr int32_t D_HALF = 32;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

// Contiguous load from GM
template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{
        1,
        static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))),
        0,
        0,
        0,
    };
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// Contiguous store to GM
template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{
        1,
        static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))),
        0,
        0,
        0,
    };
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// InterleaveRoPE Kernel
// =========================================================================

template <typename dataType>
class InterleaveRopeKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR cosGm, GM_ADDR sinGm, GM_ADDR yGm,
        int32_t totalRows, int32_t D, int32_t blockRows,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->totalRows = totalRows;
        this->D = D;
        this->blockRows = blockRows;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        uint64_t totalElems = static_cast<uint64_t>(totalRows) * static_cast<uint64_t>(D);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cosGm), totalElems);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sinGm), totalElems);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalElems);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        constexpr uint32_t kD = static_cast<uint32_t>(D_CONST);

        // Typed buffers for GM↔UB data movement
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kD * sizeof(dataType));
        pipe.InitBuffer(cosQueue_, BUFFER_NUM, kD * sizeof(dataType));
        pipe.InitBuffer(sinQueue_, BUFFER_NUM, kD * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kD * sizeof(dataType));

        // Float32 compute buffers
        pipe.InitBuffer(xBuf_, kD * sizeof(float));
        pipe.InitBuffer(cosBuf_, kD * sizeof(float));
        pipe.InitBuffer(sinBuf_, kD * sizeof(float));
        pipe.InitBuffer(outBuf_, kD * sizeof(float));
        pipe.InitBuffer(evenBuf_, static_cast<uint32_t>(D_HALF) * sizeof(float));
        pipe.InitBuffer(oddBuf_, static_cast<uint32_t>(D_HALF) * sizeof(float));
        pipe.InitBuffer(negOddBuf_, static_cast<uint32_t>(D_HALF) * sizeof(float));
        pipe.InitBuffer(tmpBuf_, static_cast<uint32_t>(D_HALF) * sizeof(float));

        // Cast buffers for non-float types
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, kD * sizeof(float));
            pipe.InitBuffer(cosCastBuf_, kD * sizeof(float));
            pipe.InitBuffer(sinCastBuf_, kD * sizeof(float));
            pipe.InitBuffer(yCastBuf_, kD * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int32_t rowBlocks = CeilDivU32(static_cast<uint32_t>(totalRows),
                                                  static_cast<uint32_t>(blockRows));

            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int32_t bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= rowBlocks) { continue; }

                const int32_t rowStart = bx * blockRows;
                const int32_t rowEnd = (rowStart + blockRows <= totalRows)
                                           ? (rowStart + blockRows)
                                           : totalRows;

                for (int32_t row = rowStart; row < rowEnd; ++row) {
                    ProcessRow(row);
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[offset], static_cast<uint32_t>(D));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyInCos(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        cosInLocal_ = cosQueue_.AllocTensor<dataType>();
        LoadGmToUb(cosInLocal_, cosGM_[offset], static_cast<uint32_t>(D));
        cosQueue_.EnQue(cosInLocal_);
    }

    __aicore__ inline void CopyInSin(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        sinInLocal_ = sinQueue_.AllocTensor<dataType>();
        LoadGmToUb(sinInLocal_, sinGM_[offset], static_cast<uint32_t>(D));
        sinQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[offset], yOutLocal_, static_cast<uint32_t>(D));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    // Helper: prepare float32 tensor from typed tensor (with optional cast)
    template <typename SrcT>
    __aicore__ inline void PrepareFloat(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<SrcT> &src,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
        int32_t count)
    {
        if constexpr (std::is_same_v<SrcT, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            dst = castBuf.Get<float>();
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        }
    }

    // Helper: finalize float32 tensor to typed tensor (with optional cast)
    template <typename DstT>
    __aicore__ inline void FinalizeTyped(
        AscendC::LocalTensor<DstT> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        if constexpr (!std::is_same_v<DstT, float>) {
            AscendC::RoundMode roundMode = AscendC::RoundMode::CAST_NONE;
            if constexpr (std::is_same_v<DstT, bfloat16_t>) {
                roundMode = AscendC::RoundMode::CAST_ROUND;
            }
            AscendC::Cast(dst, src, roundMode, count);
        }
    }

    // Extract even-indexed elements from src[D] to dst[D/2]
    // Uses UB-to-UB DataCopy with stride
    __aicore__ inline void ExtractEvens(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        AscendC::DataCopyParams copyParams{
            static_cast<uint16_t>(count),
            static_cast<uint16_t>(sizeof(float)),
            static_cast<uint16_t>(2 * sizeof(float)),
            0,
        };
        AscendC::DataCopy(dst, src, copyParams);
    }

    // Extract odd-indexed elements from src[D] to dst[D/2]
    // Uses UB-to-UB DataCopy with stride, starting from src[1]
    __aicore__ inline void ExtractOdds(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        AscendC::DataCopyParams copyParams{
            static_cast<uint16_t>(count),
            static_cast<uint16_t>(sizeof(float)),
            static_cast<uint16_t>(2 * sizeof(float)),
            0,
        };
        AscendC::DataCopy(dst, src[1], copyParams);
    }

    __aicore__ inline void ComputeRow()
    {
        constexpr int32_t kD = D_CONST;
        constexpr int32_t kDHalf = D_HALF;

        // Get float32 buffers
        xLocal_ = xBuf_.Get<float>();
        cosLocal_ = cosBuf_.Get<float>();
        sinLocal_ = sinBuf_.Get<float>();
        outLocal_ = outBuf_.Get<float>();
        evenLocal_ = evenBuf_.Get<float>();
        oddLocal_ = oddBuf_.Get<float>();
        negOddLocal_ = negOddBuf_.Get<float>();
        tmpLocal_ = tmpBuf_.Get<float>();

        // Allocate output typed buffer
        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

        // Dequeue inputs
        xInLocal_ = xInQueue_.DeQue<dataType>();
        cosInLocal_ = cosQueue_.DeQue<dataType>();
        sinInLocal_ = sinQueue_.DeQue<dataType>();

        // Cast inputs to float32
        PrepareFloat(xLocal_, xInLocal_, xCastBuf_, kD);
        PrepareFloat(cosLocal_, cosInLocal_, cosCastBuf_, kD);
        PrepareFloat(sinLocal_, sinInLocal_, sinCastBuf_, kD);

        // ---- Extract evens and odds from x ----
        // evens = x[0], x[2], ..., x[62]
        ExtractEvens(evenLocal_, xLocal_, kDHalf);
        // odds = x[1], x[3], ..., x[63]
        ExtractOdds(oddLocal_, xLocal_, kDHalf);

        // ---- Compute ----
        // Negate odds for rotation: neg_odds = -odds
        AscendC::Muls(negOddLocal_, oddLocal_, -1.0f, kDHalf);

        // out_first_half = evens * cos_first_half + (-odds) * sin_first_half
        AscendC::Mul(outLocal_, evenLocal_, cosLocal_, kDHalf);
        AscendC::Mul(tmpLocal_, negOddLocal_, sinLocal_, kDHalf);
        AscendC::Add(outLocal_, outLocal_, tmpLocal_, kDHalf);

        // out_second_half = odds * cos_second_half + evens * sin_second_half
        AscendC::Mul(outLocal_[kDHalf], oddLocal_, cosLocal_[kDHalf], kDHalf);
        AscendC::Mul(tmpLocal_, evenLocal_, sinLocal_[kDHalf], kDHalf);
        AscendC::Add(outLocal_[kDHalf], outLocal_[kDHalf], tmpLocal_, kDHalf);

        // Finalize: cast float32 → dataType
        FinalizeTyped(yOutLocal_, outLocal_, kD);

        // Free input tensors
        xInQueue_.FreeTensor(xInLocal_);
        cosQueue_.FreeTensor(cosInLocal_);
        sinQueue_.FreeTensor(sinInLocal_);

        // Enqueue output
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t row)
    {
        CopyInX(row);
        CopyInCos(row);
        CopyInSin(row);
        ComputeRow();
        CopyOutY(row);
    }

private:
    int32_t totalRows = 0;
    int32_t D = 0;
    int32_t blockRows = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> cosGM_;
    AscendC::GlobalTensor<dataType> sinGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    // TQue for GM↔UB DMA
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;

    // TBuf for float32 compute
    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cosBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sinBuf_;
