51	        hiddenDimCountLastLoop_ = tilingData_->hiddenDimCountLastLoopPerBlock;
52	        if (GetBlockIdx() == GetBlockNum() - 1) {
53	            curBlockBatchs_ = tilingData_->batchsLastBlock;
54	            hiddenDimLoops_ = tilingData_->hiddenDimLoopsLastBlock;
55	            hiddenDimCountPerLoop_ = tilingData_->hiddenDimCountPerLoopLastBlock;
56	            hiddenDimCountLastLoop_ = tilingData_->hiddenDimCountLastLoopLastBlock;
57	        }
58	
59	        xGm.SetGlobalBuffer((__gm__ T*)x);
60	        yGm.SetGlobalBuffer((__gm__ T*)y);
61	        cosGm.SetGlobalBuffer((__gm__ T*)cos);
62	        sinGm.SetGlobalBuffer((__gm__ T*)sin);
63	
64	        // init pipe
65	        pipe_->InitBuffer(inQueueX, 1, hiddenDimCountPerLoop_ * hiddenDim * sizeof(T));
66	        pipe_->InitBuffer(outQueueY, 1, hiddenDimCountPerLoop_ * hiddenDim * sizeof(float) * numTwo);
67	        pipe_->InitBuffer(inQueueCos, 1, hiddenDimCountPerLoop_ * hiddenDim * sizeof(float) * numTwo);
68	        pipe_->InitBuffer(inQueueSin, 1, hiddenDimCountPerLoop_ * hiddenDim * sizeof(float) * numTwo);
69	
70	        pipe_->InitBuffer(bufferReal, hiddenDimCountPerLoop_ * hiddenDimHalf * sizeof(float) * numTwo);
71	        pipe_->InitBuffer(bufferImag, hiddenDimCountPerLoop_ * hiddenDimHalf * sizeof(float) * numTwo);
72	        pipe_->InitBuffer(buffer_, hiddenDimCountPerLoop_ * hiddenDim * sizeof(float));
73	    }
74	
75	    __aicore__ inline void Process()
76	    {
77	        for (int64_t i = 0; i < curBlockBatchs_; i++) {
78	            Rope(i);
79	        }
80	    }
81	
82	    __aicore__ inline void Rope(int64_t idx)
83	    {
84	        int64_t hiddenDimCount = hiddenDimCountPerLoop_;
85	        for (int64_t hiddenDimLoop = 0; hiddenDimLoop < hiddenDimLoops_; hiddenDimLoop++) {
86	            if (hiddenDimLoop == hiddenDimLoops_ - 1) {
87	                hiddenDimCount = hiddenDimCountLastLoop_;
88	            }
89	            int64_t sinCosIdxOffset = ((GetBlockIdx() * tilingData_->batchsPerBlock + idx) * seqLength_ +
90	                                       hiddenDimLoop * hiddenDimCountPerLoop_) *
91	                                      hiddenDim;
92	            LocalTensor<float> cosLocal = inQueueCos.AllocTensor<float>();
93	            DataCopy(
94	                cosLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(), cosGm[sinCosIdxOffset],
95	                hiddenDimCount * hiddenDim);
96	
97	            inQueueCos.EnQue(cosLocal);
98	            cosLocal = inQueueCos.DeQue<float>();
99	            Cast(
100	                cosLocal, cosLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(), RoundMode::CAST_NONE,
101	                hiddenDimCount * hiddenDim);
102	
103	            LocalTensor<float> sinLocal = inQueueSin.AllocTensor<float>();
104	            DataCopy(
105	                sinLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(), sinGm[sinCosIdxOffset],
106	                hiddenDimCount * hiddenDim);
107	            inQueueSin.EnQue(sinLocal);
108	            sinLocal = inQueueSin.DeQue<float>();
109	            Cast(
110	                sinLocal, sinLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(), RoundMode::CAST_NONE,
111	                hiddenDimCount * hiddenDim);
112	
113	            int64_t batchOffset = (GetBlockIdx() * tilingData_->batchsPerBlock + idx) * numHead_ * seqLength_;
114	            for (int64_t nIdx = 0; nIdx < numHead_; nIdx++) {
115	                int64_t xOffset =
116	                    (batchOffset + nIdx * seqLength_ + hiddenDimLoop * hiddenDimCountPerLoop_) * hiddenDim;
117	                // load xLocal
118	                LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
119	                DataCopy(xLocal, xGm[xOffset], hiddenDimCount * hiddenDim);
120	                inQueueX.EnQue(xLocal);
121	                xLocal = inQueueX.DeQue<T>();
122	
123	                // split Real and Imag
124	                LocalTensor<float> realLocal = bufferReal.Get<float>();
125	                LocalTensor<float> imagLocal = bufferImag.Get<float>();
126	                LocalTensor<float> buf_ = buffer_.Get<float>();
127	                uint64_t rsvdCnt = 0;
128	                GatherMask(
129	                    realLocal[hiddenDimCount * hiddenDimHalf].template ReinterpretCast<T>(), xLocal, 1, true,
130	                    hiddenDimCount * hiddenDim, {1, 1, 8, 0}, rsvdCnt);
131	                GatherMask(
132	                    imagLocal[hiddenDimCount * hiddenDimHalf].template ReinterpretCast<T>(), xLocal, numTwo, true,
133	                    hiddenDimCount * hiddenDim, {1, 1, 8, 0}, rsvdCnt);
134	                Cast(
135	                    realLocal, realLocal[hiddenDimCount * hiddenDimHalf].template ReinterpretCast<T>(),
136	                    RoundMode::CAST_NONE, hiddenDimCount * hiddenDimHalf);
137	                Cast(
138	                    imagLocal, imagLocal[hiddenDimCount * hiddenDimHalf].template ReinterpretCast<T>(),
139	                    RoundMode::CAST_NONE, hiddenDimCount * hiddenDimHalf);
140	                inQueueX.FreeTensor(xLocal);
141	
142	                uint64_t mask[numTwo] = {0xffffffff, 0}; // mask hiddenDimHalf Elements
143	                LocalTensor<float> outLocal = outQueueY.AllocTensor<float>();
144	                Mul(outLocal, realLocal, cosLocal, mask, hiddenDimCount, {1, 1, 1, 8, 4, 8});
145	                Mul(outLocal[hiddenDimHalf], imagLocal, cosLocal[hiddenDimHalf], mask, hiddenDimCount,
146	                    {1, 1, 1, 8, 4, 8});
147	                PipeBarrier<PIPE_V>();
148	                Muls<float>(imagLocal, imagLocal, -1.0f, hiddenDimCount * hiddenDimHalf);
149	                PipeBarrier<PIPE_V>();
150	                Mul(buf_, imagLocal, sinLocal, mask, hiddenDimCount, {1, 1, 1, 8, 4, 8});
151	                Mul(buf_[hiddenDimHalf], realLocal, sinLocal[hiddenDimHalf], mask, hiddenDimCount, {1, 1, 1, 8, 4, 8});
152	                PipeBarrier<PIPE_V>();
153	                Add(outLocal, outLocal, buf_, hiddenDimCount * hiddenDim);
154	                PipeBarrier<PIPE_V>();
155	                Cast(
156	                    outLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(), outLocal, RoundMode::CAST_RINT,
157	                    hiddenDimCount * hiddenDim);
158	                PipeBarrier<PIPE_V>();
159	                outQueueY.EnQue(outLocal);
160	                outLocal = outQueueY.DeQue<float>();
161	                DataCopy(
162	                    yGm[xOffset], outLocal[hiddenDimCount * hiddenDim].template ReinterpretCast<T>(),
163	                    hiddenDimCount * hiddenDim);
164	                outQueueY.FreeTensor(outLocal);
165	            }
166	            inQueueCos.FreeTensor(cosLocal);
167	            inQueueSin.FreeTensor(sinLocal);
168	        }
169	    }
170	
171	private:
172	    TPipe* pipe_ = nullptr;
173	    const InterleaveRopeTilingData* tilingData_;
174	    GlobalTensor<T> xGm;
175	    GlobalTensor<T> yGm;
176	    GlobalTensor<T> cosGm;
177	    GlobalTensor<T> sinGm;
178	
179	    TQue<QuePosition::VECIN, 1> inQueueX;
180	    TQue<QuePosition::VECIN, 1> inQueueCos;
181	    TQue<QuePosition::VECIN, 1> inQueueSin;
182	    TQue<QuePosition::VECOUT, 1> outQueueY;
183	    TBuf<TPosition::VECCALC> bufferReal;
184	    TBuf<TPosition::VECCALC> bufferImag;
185	    TBuf<TPosition::VECCALC> buffer_;
186	    int64_t numHead_ = 0;
187	    int64_t seqLength_ = 0;
188	    int64_t NS_ = 0;
189	
190	    constexpr static int64_t hiddenDim = 64;
191	    constexpr static int64_t hiddenDimHalf = 32;
192	    constexpr static int64_t numTwo = 2;
193	    int64_t batchLoops_ = 0;
194	    int64_t batchPerLoop_ = 0;
195	    int64_t batchLastLoop_ = 0;
196	
197	    int64_t batchsPerBlock_ = 0;
198	    int64_t curBlockBatchs_ = 0;
199	    int64_t hiddenDimLoops_ = 0;
200	    int64_t hiddenDimCountPerLoop_ = 0;
201	    int64_t hiddenDimCountLastLoop_ = 0;
202	};
