12	 * \file interleave_rope_fixed_bnsd_b11d.h
13	 * \brief
14	 */
15	#ifndef _INTERLEAVE_ROPE_FIX_BNSD_B11D_H_
16	#define _INTERLEAVE_ROPE_FIX_BNSD_B11D_H_
17	#include "platform/platform_infos_def.h"
18	#include "kernel_operator.h"
19	
20	namespace InterleaveRope {
21	using namespace AscendC;
22	
23	template <typename T>
24	class KernelInterleaveRopeFixBNSD {
25	public:
26	    __aicore__ inline KernelInterleaveRopeFixBNSD(TPipe* pipe, const InterleaveRopeTilingData* tiling)
27	        : pipe_(pipe), tilingData_(tiling)
28	    {}
29	
30	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR y)
31	    {
32	        /*
33	         * original shape:
34	         * x:   [32, 32, 1, 64]
35	         * cos: [32, 1,  1, 64]
36	         * sin: [32, 1,  1, 64]
37	         * y:   [32, 32, 1, 64]
38	         * For each block, process
39	         * x:   [4, 32, 1, 64]
40	         * cos: [4, 1,  1, 64]
41	         * sin: [4, 1,  1, 64]
42	         * y:   [4, 32, 1, 64]
43	         */
44	
45	        // init global memory
46	        xGm.SetGlobalBuffer(
47	            (__gm__ T*)x + GetBlockIdx() * tilingData_->batchsPerBlock * numHead * hiddenDim,
48	            tilingData_->batchsPerBlock * numHead * hiddenDim);
49	        cosGm.SetGlobalBuffer(
50	            (__gm__ T*)cos + GetBlockIdx() * tilingData_->batchsPerBlock * hiddenDim,
51	            tilingData_->batchsPerBlock * hiddenDim);
52	        sinGm.SetGlobalBuffer(
53	            (__gm__ T*)sin + GetBlockIdx() * tilingData_->batchsPerBlock * hiddenDim,
54	            tilingData_->batchsPerBlock * hiddenDim);
55	        yGm.SetGlobalBuffer(
56	            (__gm__ T*)y + GetBlockIdx() * tilingData_->batchsPerBlock * numHead * hiddenDim,
57	            tilingData_->batchsPerBlock * numHead * hiddenDim);
58	
59	        // init pipe
60	        pipe_->InitBuffer(inQueueX, 1, tilingData_->batchsPerBlock * numHead * hiddenDim * sizeof(T));
61	        pipe_->InitBuffer(outQueueY, 1, tilingData_->batchsPerBlock * numHead * hiddenDim * sizeof(float) * numTwo);
62	
63	        pipe_->InitBuffer(inQueueCos, 1, tilingData_->batchsPerBlock * hiddenDim * sizeof(float) * numTwo);
64	        pipe_->InitBuffer(inQueueSin, 1, tilingData_->batchsPerBlock * hiddenDim * sizeof(float) * numTwo);
65	
66	        pipe_->InitBuffer(bufferReal, tilingData_->batchsPerBlock * numHead * hiddenDimHalf * sizeof(float) * numTwo);
67	        pipe_->InitBuffer(bufferImag, tilingData_->batchsPerBlock * numHead * hiddenDimHalf * sizeof(float) * numTwo);
68	        pipe_->InitBuffer(buffer_, tilingData_->batchsPerBlock * numHead * hiddenDim * sizeof(float) * numTwo);
69	    }
70	
71	    __aicore__ inline void Process()
72	    {
73	        Rope();
74	    }
75	
76	    __aicore__ inline void Rope()
77	    {
78	        // load
79	        LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
80	        DataCopy(xLocal, xGm, tilingData_->batchsPerBlock * numHead * hiddenDim);
81	        inQueueX.EnQue(xLocal);
82	        xLocal = inQueueX.DeQue<T>();
83	
84	        // split Real and Imag
85	        LocalTensor<float> realLocal = bufferReal.Get<float>();
86	        LocalTensor<float> imagLocal = bufferImag.Get<float>();
87	        LocalTensor<float> buf_ = buffer_.Get<float>();
88	        uint64_t rsvdCnt = 0;
89	        GatherMask(
90	            realLocal[tilingData_->batchsPerBlock * numHead * hiddenDimHalf].template ReinterpretCast<T>(), xLocal, 1,
91	            true, tilingData_->batchsPerBlock * numHead * hiddenDim, {1, 1, 8, 0}, rsvdCnt);
92	        GatherMask(
93	            imagLocal[tilingData_->batchsPerBlock * numHead * hiddenDimHalf].template ReinterpretCast<T>(), xLocal,
94	            numTwo, true, tilingData_->batchsPerBlock * numHead * hiddenDim, {1, 1, 8, 0}, rsvdCnt);
95	        PipeBarrier<PIPE_V>();
96	        Cast(
97	            realLocal, realLocal[tilingData_->batchsPerBlock * numHead * hiddenDimHalf].template ReinterpretCast<T>(),
98	            RoundMode::CAST_NONE, tilingData_->batchsPerBlock * numHead * hiddenDimHalf);
99	        Cast(
100	            imagLocal, imagLocal[tilingData_->batchsPerBlock * numHead * hiddenDimHalf].template ReinterpretCast<T>(),
101	            RoundMode::CAST_NONE, tilingData_->batchsPerBlock * numHead * hiddenDimHalf);
102	
103	        inQueueX.FreeTensor(xLocal);
104	
105	        // rope
106	        LocalTensor<float> cosLocal = inQueueCos.AllocTensor<float>();
107	        DataCopy(
108	            cosLocal[tilingData_->batchsPerBlock * hiddenDim].template ReinterpretCast<T>(), cosGm,
109	            tilingData_->batchsPerBlock * hiddenDim);
110	
111	        inQueueCos.EnQue(cosLocal);
112	        cosLocal = inQueueCos.DeQue<float>();
113	
114	        Cast(
115	            cosLocal, cosLocal[tilingData_->batchsPerBlock * hiddenDim].template ReinterpretCast<T>(),
116	            RoundMode::CAST_NONE, tilingData_->batchsPerBlock * hiddenDim);
117	        PipeBarrier<PIPE_V>();
118	        uint64_t mask[numTwo] = {0xffffffff, 0};
119	        LocalTensor<float> outLocal = outQueueY.AllocTensor<float>();
120	        for (int64_t i = 0; i < tilingData_->batchsPerBlock; i++) {
121	            Mul(outLocal[i * numHead * hiddenDim], realLocal[i * numHead * hiddenDimHalf], cosLocal[i * hiddenDim],
122	                mask, hiddenDim, {1, 1, 1, 8, 4, 0});
123	            Mul(outLocal[i * numHead * hiddenDim + numHead], imagLocal[i * numHead * hiddenDimHalf],
124	                cosLocal[i * hiddenDim + hiddenDimHalf], mask, hiddenDim, {1, 1, 1, 8, 4, 0});
125	        }
126	        PipeBarrier<PIPE_V>();
127	        inQueueCos.FreeTensor(cosLocal);
128	
129	        LocalTensor<float> sinLocal = inQueueSin.AllocTensor<float>();
130	
131	        DataCopy(
132	            sinLocal[tilingData_->batchsPerBlock * hiddenDim].template ReinterpretCast<T>(), sinGm,
133	            tilingData_->batchsPerBlock * hiddenDim);
134	
135	        inQueueSin.EnQue(sinLocal);
136	        sinLocal = inQueueSin.DeQue<float>();
137	        Cast(
138	            sinLocal, sinLocal[tilingData_->batchsPerBlock * hiddenDim].template ReinterpretCast<T>(),
139	            RoundMode::CAST_NONE, tilingData_->batchsPerBlock * hiddenDim);
140	        PipeBarrier<PIPE_V>();
141	        Muls<float>(imagLocal, imagLocal, -1.0f, tilingData_->batchsPerBlock * numHead * hiddenDimHalf);
142	        PipeBarrier<PIPE_V>();
143	        for (int64_t i = 0; i < tilingData_->batchsPerBlock; i++) {
144	            Mul(buf_[i * numHead * hiddenDim], imagLocal[i * numHead * hiddenDimHalf], sinLocal[i * hiddenDim], mask,
145	                hiddenDim, {1, 1, 1, 8, 4, 0});
146	            Mul(buf_[i * numHead * hiddenDim + hiddenDimHalf], realLocal[i * numHead * hiddenDimHalf],
147	                sinLocal[i * hiddenDim + hiddenDimHalf], mask, hiddenDim, {1, 1, 1, 8, 4, 0});
148	        }
149	        PipeBarrier<PIPE_V>();
150	        inQueueSin.FreeTensor(sinLocal);
151	        Add(outLocal, outLocal, buf_, tilingData_->batchsPerBlock * numHead * hiddenDim);
152	        PipeBarrier<PIPE_V>();
153	        Cast(
154	            outLocal[tilingData_->batchsPerBlock * numHead * hiddenDim].template ReinterpretCast<T>(), outLocal,
155	            RoundMode::CAST_RINT, tilingData_->batchsPerBlock * numHead * hiddenDim);
156	        outQueueY.EnQue(outLocal);
157	        outLocal = outQueueY.DeQue<float>();
158	        DataCopy(
159	            yGm, outLocal[tilingData_->batchsPerBlock * numHead * hiddenDim].template ReinterpretCast<T>(),
160	            tilingData_->batchsPerBlock * numHead * hiddenDim);
161	        outQueueY.FreeTensor(outLocal);
162	    }
163	
164	private:
165	    TPipe* pipe_ = nullptr;
166	    const InterleaveRopeTilingData* tilingData_;
167	    GlobalTensor<T> xGm;
168	    GlobalTensor<T> yGm;
169	    GlobalTensor<T> cosGm;
170	    GlobalTensor<T> sinGm;
171	
172	    TQue<QuePosition::VECIN, 1> inQueueX;
173	    TQue<QuePosition::VECIN, 1> inQueueCos;
174	    TQue<QuePosition::VECIN, 1> inQueueSin;
175	    TQue<QuePosition::VECOUT, 1> outQueueY;
176	    TBuf<TPosition::VECCALC> bufferReal;
177	    TBuf<TPosition::VECCALC> bufferImag;
178	    TBuf<TPosition::VECCALC> buffer_;
179	
180	    constexpr static int64_t hiddenDim = 64;
181	    constexpr static int64_t hiddenDimHalf = 32;
182	    constexpr static int64_t numHead = 32;
183	    constexpr static int64_t seqLength = 1;
184	    constexpr static int64_t numTwo = 2;
185	};
186	} // namespace InterleaveRope
