32	        /*
33	         * For each block, process
34	         * x:   [B, N, S, 64]
35	         * cos: [B, 1, S, 64]
36	         * sin: [B, 1, S, 64]
37	         * y:   [B, N, S, 64]
38	         */
39	        // tilingData
40	        int64_t blockFactor = (tilingData_->seqLength + tilingData_->blockDim - 1) / tilingData_->blockDim;
41	        int64_t currentBlockFactor = blockFactor;
42	        if (GetBlockIdx() == tilingData_->blockDim - 1) {
43	            currentBlockFactor = tilingData_->seqLength - GetBlockIdx() * blockFactor;
44	        }
45	        ubFactor = 32; // ubfactor: 32
46	        ubLoop = currentBlockFactor / ubFactor;
47	        ubTail = currentBlockFactor - ubFactor * ubLoop;
48	
49	        xGm.SetGlobalBuffer((__gm__ T*)x + GetBlockIdx() * blockFactor * ROPE_LENGTH);
50	        yGm.SetGlobalBuffer((__gm__ T*)y + GetBlockIdx() * blockFactor * ROPE_LENGTH);
51	        cosGm.SetGlobalBuffer((__gm__ T*)cos + GetBlockIdx() * blockFactor * ROPE_LENGTH);
52	        sinGm.SetGlobalBuffer((__gm__ T*)sin + GetBlockIdx() * blockFactor * ROPE_LENGTH);
53	
54	        // init pipe
55	        pipe_->InitBuffer(inQueueX, 2, ubFactor * ROPE_LENGTH * sizeof(T));          // 2*ubFactor*64*2=256*ubFactor
56	        pipe_->InitBuffer(inQueuePosEmb, 2, 2 * ubFactor * ROPE_LENGTH * sizeof(T)); // 2*2*ubFactor*64*2=512*ubFactor
57	        pipe_->InitBuffer(outQueue, 2, ubFactor * ROPE_LENGTH * sizeof(T));          // 2*ubFactor*64*2=256*ubFactor
58	        pipe_->InitBuffer(wsBuffer, 8 * ubFactor * ROPE_LENGTH * sizeof(float));     // 8*ubFactor*64*4=2048*ubFactor
59	    }
60	
61	    __aicore__ inline void Process()
62	    {
63	        LocalTensor<float> workspaceBuffer = wsBuffer.Get<float>();
64	
65	        DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
66	        DataCopyExtParams copyParamsContinguous;
67	        copyParamsContinguous.blockCount = 1;
68	        int64_t xOffset = 0;
69	        int64_t freqOffset = 0;
70	        for (int64_t batchId = 0; batchId < tilingData_->batchSize; batchId++) {
71	            copyParamsContinguous.blockLen = ubFactor * ROPE_LENGTH * sizeof(T);
72	            for (int64_t loopIdx = 0; loopIdx < ubLoop; ++loopIdx) {
73	                freqOffset = batchId * tilingData_->seqLength * ROPE_LENGTH + loopIdx * ubFactor * ROPE_LENGTH;
74	                /*
75	                 * cosLocal = [batchId, 0, :ubFactor:, 64]
76	                 * sinLocal = [batchId, 0, :ubFactor:, 64]
77	                 */
78	                LocalTensor<T> cosLocal = inQueuePosEmb.AllocTensor<T>();
79	                LocalTensor<T> sinLocal = cosLocal[ubFactor * ROPE_LENGTH];
80	                DataCopyPad(cosLocal, cosGm[freqOffset], copyParamsContinguous, padParams);
81	                DataCopyPad(sinLocal, sinGm[freqOffset], copyParamsContinguous, padParams);
82	                inQueuePosEmb.EnQue(cosLocal);
83	                cosLocal = inQueuePosEmb.DeQue<T>();
84	                sinLocal = cosLocal[ubFactor * ROPE_LENGTH];
85	
86	                for (int64_t headId = 0; headId < tilingData_->numHead; ++headId) {
87	                    xOffset = batchId * tilingData_->numHead * tilingData_->seqLength * ROPE_LENGTH +
88	                              loopIdx * ubFactor * ROPE_LENGTH + headId * tilingData_->seqLength * ROPE_LENGTH;
89	                    /*
90	                     * xLocal = [batchId, headId, seqId: seqId+ubFactor, 64]
91	                     * yLocal = [batchId, headId, seqId: seqId+ubFactor, 64]
92	                     */
93	                    LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
94	                    DataCopyPad(xLocal, xGm[xOffset], copyParamsContinguous, padParams);
95	                    inQueueX.EnQue(xLocal);
96	                    xLocal = inQueueX.DeQue<T>();
97	                    LocalTensor<T> yLocal = outQueue.AllocTensor<T>();
98	                    RoPE<T, true, ROPE_LENGTH>(yLocal, xLocal, cosLocal, sinLocal, workspaceBuffer, ubFactor);
99	                    inQueueX.FreeTensor(xLocal);
100	                    outQueue.EnQue(yLocal);

