// AscendC InterleaveRoPE kernel
// Based on the built-in interleave_rope implementation pattern.
// Uses GatherMask to deinterleave x into real (evens) and imag (odds).
// Computation: y_first = real*cos_first + (-imag)*sin_first
//              y_second = imag*cos_second + real*sin_second

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t HEAD_SIZE = 64;
constexpr int32_t HEAD_SIZE_HALF = 32;
constexpr int64_t NUM_ONE = 1;
constexpr int64_t NUM_TWO = 2;
constexpr int64_t NUM_EIGHT = 8;
constexpr int64_t NUM_FOUR = 4;

namespace {

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{
        1,
        static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))),
        0, 0, 0,
    };
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{
        1,
        static_cast<uint16_t>(count * static_cast<uint32_t>(sizeof(T))),
        0, 0, 0,
    };
    AscendC::DataCopyPad(dst, src, copyParams);
}

// Kernel class
template <typename dataType>
class InterleaveRopeKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR cosGm, GM_ADDR sinGm, GM_ADDR yGm,
        int32_t totalRows, int32_t D, int32_t blockRows,
        int32_t usedCoreNum, int32_t tasksPerCore)
    {
        this->totalRows = totalRows;
        this->D = D;
        this->blockRows = blockRows;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;

        uint64_t totalElems = static_cast<uint64_t>(totalRows) * static_cast<uint64_t>(D);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalElems);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cosGm), totalElems);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sinGm), totalElems);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalElems);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // Typed queues
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, HEAD_SIZE * sizeof(dataType));
        pipe.InitBuffer(cosQueue_, BUFFER_NUM, HEAD_SIZE * sizeof(dataType));
        pipe.InitBuffer(sinQueue_, BUFFER_NUM, HEAD_SIZE * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, HEAD_SIZE * sizeof(float) * 2);

        // Workspace buffer (8 * rows * headSize * sizeof(float) for 1 row)
        pipe.InitBuffer(wsBuf_, 8 * HEAD_SIZE * sizeof(float));

        // Cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_,  HEAD_SIZE * sizeof(float));
            pipe.InitBuffer(cosCastBuf_, HEAD_SIZE * sizeof(float));
            pipe.InitBuffer(sinCastBuf_, HEAD_SIZE * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int32_t rowBlocks = (totalRows + blockRows - 1) / blockRows;

            for (int32_t localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int32_t bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= rowBlocks) { continue; }
                const int32_t rowStart = bx * blockRows;
                const int32_t rowEnd = (rowStart + blockRows <= totalRows)
                                           ? (rowStart + blockRows)
                                           : totalRows;
                for (int32_t row = rowStart; row < rowEnd; ++row) {
                    ProcessRow(row);
                }
            }
        }
    }

private:
    __aicore__ inline void CopyInX(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[offset], static_cast<uint32_t>(D));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyInCos(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        cosInLocal_ = cosQueue_.AllocTensor<dataType>();
        LoadGmToUb(cosInLocal_, cosGM_[offset], static_cast<uint32_t>(D));
        cosQueue_.EnQue(cosInLocal_);
    }

    __aicore__ inline void CopyInSin(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        sinInLocal_ = sinQueue_.AllocTensor<dataType>();
        LoadGmToUb(sinInLocal_, sinGM_[offset], static_cast<uint32_t>(D));
        sinQueue_.EnQue(sinInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t row)
    {
        uint64_t offset = static_cast<uint64_t>(row) * static_cast<uint64_t>(D);
        yOutLocal_ = yOutQueue_.DeQue<float>();
        StoreUbToGm(yGM_[offset],
                    yOutLocal_[HEAD_SIZE].template ReinterpretCast<dataType>(),
                    static_cast<uint32_t>(D));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow()
    {
        constexpr int32_t kD = HEAD_SIZE;
        constexpr int32_t kDHalf = HEAD_SIZE_HALF;

        // Get workspace sub-buffers (matching split_s layout)
        LocalTensor<float> wsLocal = wsBuf_.Get<float>();
        LocalTensor<float> cosLocalFp32 = wsLocal;                            // [0, D)
        LocalTensor<float> sinLocalFp32 = wsLocal[kD];                        // [D, 2D)
        LocalTensor<float> y0 = wsLocal[kD * 2];                              // [2D, 3D)
        LocalTensor<float> y1 = wsLocal[kD * 3];                              // [3D, 4D)
        LocalTensor<float> realLocalFp32 = wsLocal[kD * 4];                   // [4D, 5D)
        LocalTensor<float> imagLocalFp32 = wsLocal[kD * 5];                   // [5D, 6D)
        LocalTensor<dataType> realLocal = wsLocal[kD * 6].template ReinterpretCast<dataType>(); // [6D, 7D)
        LocalTensor<dataType> imagLocal = wsLocal[kD * 7].template ReinterpretCast<dataType>(); // [7D, 8D)

        // Allocate output
        yOutLocal_ = yOutQueue_.AllocTensor<float>();

        // Dequeue inputs
        xInLocal_ = xInQueue_.DeQue<dataType>();
        cosInLocal_ = cosQueue_.DeQue<dataType>();
        sinInLocal_ = sinQueue_.DeQue<dataType>();

        // Step 1: Cast cos and sin to float32
        AscendC::Cast(cosLocalFp32, cosInLocal_, AscendC::RoundMode::CAST_NONE, kD);
        AscendC::Cast(sinLocalFp32, sinInLocal_, AscendC::RoundMode::CAST_NONE, kD);
        AscendC::PipeBarrier<PIPE_V>();

        // Step 2: GatherMask deinterleave x into real (evens) and imag (odds)
        uint64_t rsvdCnt = 0;
        AscendC::GatherMask(realLocal, xInLocal_, NUM_ONE, true, kD,
                            {NUM_ONE, NUM_ONE, NUM_EIGHT, 0}, rsvdCnt);
        AscendC::GatherMask(imagLocal, xInLocal_, NUM_TWO, true, kD,
                            {NUM_ONE, NUM_ONE, NUM_EIGHT, 0}, rsvdCnt);
        AscendC::PipeBarrier<PIPE_V>();

        // Step 3: Cast real and imag to float32
        AscendC::Cast(realLocalFp32, realLocal, AscendC::RoundMode::CAST_NONE, kDHalf);
        AscendC::Cast(imagLocalFp32, imagLocal, AscendC::RoundMode::CAST_NONE, kDHalf);
        AscendC::PipeBarrier<PIPE_V>();

        // Step 4: y0 = (real, imag) * cos
        uint64_t mask64 = 0xffffffff;
        AscendC::Mul(y0, realLocalFp32, cosLocalFp32, mask64, 1,
                     {NUM_ONE, NUM_ONE, NUM_ONE, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
        AscendC::Mul(y0[kDHalf], imagLocalFp32, cosLocalFp32[kDHalf], mask64, 1,
                     {NUM_ONE, NUM_ONE, NUM_ONE, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
        AscendC::PipeBarrier<PIPE_V>();

        // Step 5: y1 = (-imag, real) * sin
        AscendC::Muls<float>(imagLocalFp32, imagLocalFp32, -1.0f, kDHalf);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(y1, imagLocalFp32, sinLocalFp32, mask64, 1,
                     {NUM_ONE, NUM_ONE, NUM_ONE, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
        AscendC::Mul(y1[kDHalf], realLocalFp32, sinLocalFp32[kDHalf], mask64, 1,
                     {NUM_ONE, NUM_ONE, NUM_ONE, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
        AscendC::PipeBarrier<PIPE_V>();

        // Step 6: y0 = y0 + y1
        AscendC::Add(y0, y0, y1, kD);
        AscendC::PipeBarrier<PIPE_V>();

        // Step 7: Cast result to dataType (store back to typed output area)
        if constexpr (std::is_same_v<dataType, bfloat16_t>) {
            AscendC::Cast(yOutLocal_[kD].template ReinterpretCast<dataType>(), y0,
                          AscendC::RoundMode::CAST_RINT, kD);
        } else {
            AscendC::Cast(yOutLocal_[kD].template ReinterpretCast<dataType>(), y0,
                          AscendC::RoundMode::CAST_NONE, kD);
        }

        // Free inputs
        xInQueue_.FreeTensor(xInLocal_);
        cosQueue_.FreeTensor(cosInLocal_);
        sinQueue_.FreeTensor(sinInLocal_);

        // Enqueue output
        yOutQueue_.EnQue(yOutLocal_);
    }

    __aicore__ inline void ProcessRow(int32_t row)
    {
        CopyInX(row);
        CopyInCos(row);
        CopyInSin(row);
        ComputeRow();
        CopyOutY(row);
    }

private:
    int32_t totalRows = 0;
    int32_t D = 0;
    int32_t blockRows = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> cosGM_;
    AscendC::GlobalTensor<dataType> sinGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wsBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cosCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sinCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> cosInLocal_;
    AscendC::LocalTensor<dataType> sinInLocal_;
    AscendC::LocalTensor<float> yOutLocal_;
};

} // namespace

// Kernel entry point
extern "C" __global__ __aicore__ void interleave_rope(
    GM_ADDR xGm, GM_ADDR cosGm, GM_ADDR sinGm, GM_ADDR yGm,
    int32_t totalRows, int32_t D, int32_t blockRows,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        InterleaveRopeKernel<float> kernel;
        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        InterleaveRopeKernel<half> kernel;
        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    } else {
        InterleaveRopeKernel<bfloat16_t> kernel;
        kernel.Init(xGm, cosGm, sinGm, yGm, totalRows, D, blockRows, usedCoreNum, tasksPerCore);
        kernel.Process();
    }
}
